 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == color:
                        seen.add(q)
                        todo.append(q)
            r0, c0 = min(y for y,x in cells), min(x for y,x in cells)
            shape = [(y-r0, x-c0) for y,x in cells]
            hh = max(y for y,x in shape) + 1
            ww = max(x for y,x in shape) + 1
            comps.append((c0, r0, color, shape, hh, ww))
    comps.sort(key=lambda z: (z[0], z[1]))
    if not comps:
        return [[0]*w for _ in range(h)]

    # The separated pieces are reassembled in their left-to-right order as a
    # down-right staircase. The leading pair is edge/diagonal joined when possible;
    # later pieces continue from the preceding piece's lower-right corner.
    positions = [(0, 0)]
    for i in range(1, len(comps)):
        _, _, _, _, ph, pw = comps[i-1]
        _, _, _, _, ch, _ = comps[i]
        dr = ph if i == 1 and ch <= ph else ph - 1
        dc = pw - 1
        pr, pc = positions[-1]
        positions.append((pr + dr, pc + dc))

    # Keep the assembled staircase inside the original canvas by using the
    # available overlap at the leading join if the full chain would exceed it.
    def bottom():
        return max(pos[0] + comp[4] for pos, comp in zip(positions, comps))
    while bottom() > h:
        changed = False
        for i in range(1, len(positions)):
            _, _, _, _, ph, _ = comps[i-1]
            min_dr = ph - 1
            actual = positions[i][0] - positions[i-1][0]
            if actual > min_dr:
                reduction = min(actual - min_dr, bottom() - h)
                for j in range(i, len(positions)):
                    positions[j] = (positions[j][0] - reduction, positions[j][1])
                changed = True
                break
        if not changed:
            break

    out = [[0]*w for _ in range(h)]
    for (r0, c0), comp in zip(positions, comps):
        _, _, color, shape, _, _ = comp
        for dr, dc in shape:
            y, x = r0 + dr, c0 + dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
